/** The VS Code extension's extension.js. It reads the product from product.json beside it. */
export const VSCODE_EXTENSION_SOURCE: string = "// A VS Code extension for one Muse Muse product, generated from its musemuse.json. Each of the product's actions is a\n// command: it asks for the action's fields, sends them to the live product and opens the reply as JSON.\n// No dependencies. Built with Muse Muse, a hackathon concept. Not an official Meta product.\n\"use strict\";\n\nconst vscode = require(\"vscode\");\nconst PRODUCT = require(\"./product.json\");\n\nconst TIMEOUT_MS = 120000;\nconst MAX_FIELDS = 8;\n\n/** The address the actions run at: the setting when it is a web address, else the live product. */\nfunction baseUrl() {\n  const set = String(vscode.workspace.getConfiguration(PRODUCT.configSection).get(\"baseUrl\") || \"\").trim().replace(/\\/+$/, \"\");\n  return /^https:\\/\\/[^\\s/]+/.test(set) || /^http:\\/\\/(localhost|127\\.0\\.0\\.1)(:\\d+)?(\\/|$)/.test(set) ? set : PRODUCT.liveUrl.replace(/\\/+$/, \"\");\n}\n\n/** The editor's selected text, for the first text field. */\nfunction selection() {\n  const editor = vscode.window.activeTextEditor;\n  if (!editor || editor.selection.isEmpty) return \"\";\n  return editor.document.getText(editor.selection);\n}\n\nfunction words(name) {\n  return String(name).replace(/[_-]+/g, \" \").replace(/([a-z0-9])([A-Z])/g, \"$1 $2\").toLowerCase();\n}\n\n/** Asks for one field. Resolves undefined when the person cancels, and null for an optional field left empty. */\nasync function askField(name, schema, required, prefill) {\n  const label = `${words(name)}${required ? \"\" : \" (optional)\"}`;\n  const about = typeof schema.description === \"string\" ? schema.description.slice(0, 200) : \"\";\n  if (Array.isArray(schema.enum) && schema.enum.length) {\n    const items = schema.enum.map((v) => ({ label: String(v), value: v }));\n    if (!required) items.push({ label: \"Leave it out\", value: null });\n    const picked = await vscode.window.showQuickPick(items, { title: label, placeHolder: about || undefined, ignoreFocusOut: true });\n    return picked === undefined ? undefined : picked.value;\n  }\n  if (schema.type === \"boolean\") {\n    const items = [{ label: \"Yes\", value: true }, { label: \"No\", value: false }];\n    if (!required) items.push({ label: \"Leave it out\", value: null });\n    const picked = await vscode.window.showQuickPick(items, { title: label, placeHolder: about || undefined, ignoreFocusOut: true });\n    return picked === undefined ? undefined : picked.value;\n  }\n  const numeric = schema.type === \"number\" || schema.type === \"integer\";\n  const text = schema.type === \"string\";\n  const typed = await vscode.window.showInputBox({\n    title: label,\n    prompt: about || (text ? undefined : \"As JSON\"),\n    value: prefill || (text || numeric ? \"\" : schema.type === \"array\" ? \"[]\" : \"\"),\n    ignoreFocusOut: true,\n    validateInput(value) {\n      if (!value && !required) return null;\n      if (!value) return \"This one is needed.\";\n      if (numeric) return Number.isFinite(Number(value)) && (schema.type !== \"integer\" || Number.isInteger(Number(value))) ? null : \"Type a number.\";\n      if (text) return null;\n      try {\n        JSON.parse(value);\n        return null;\n      } catch {\n        return \"Type it as JSON.\";\n      }\n    },\n  });\n  if (typed === undefined) return undefined;\n  if (!typed && !required) return null;\n  if (numeric) return Number(typed);\n  if (text) return typed;\n  return JSON.parse(typed);\n}\n\n/** The action's input, asked field by field, or as one JSON object when its schema has no fields to ask for. */\nasync function collectInput(action) {\n  const schema = action.input && typeof action.input === \"object\" ? action.input : {};\n  const props = schema.properties && typeof schema.properties === \"object\" ? schema.properties : null;\n  if (!props || !Object.keys(props).length || Object.keys(props).length > MAX_FIELDS) {\n    const typed = await vscode.window.showInputBox({\n      title: `${action.title}: the input, as JSON`,\n      value: JSON.stringify(action.example || {}),\n      ignoreFocusOut: true,\n      validateInput(value) {\n        try {\n          const v = JSON.parse(value);\n          return v && typeof v === \"object\" && !Array.isArray(v) ? null : \"Type a JSON object.\";\n        } catch {\n          return \"Type it as JSON.\";\n        }\n      },\n    });\n    return typed === undefined ? undefined : JSON.parse(typed);\n  }\n  const required = new Set(Array.isArray(schema.required) ? schema.required : []);\n  const names = Object.keys(props).sort((a, b) => Number(required.has(b)) - Number(required.has(a)));\n  let prefill = selection();\n  const input = {};\n  for (const name of names) {\n    const field = props[name] && typeof props[name] === \"object\" ? props[name] : {};\n    const value = await askField(name, field, required.has(name), field.type === \"string\" ? prefill : \"\");\n    if (value === undefined) return undefined;\n    if (field.type === \"string\" && prefill) prefill = \"\";\n    if (value !== null) input[name] = value;\n  }\n  return input;\n}\n\nasync function run(action, out) {\n  const input = await collectInput(action);\n  if (input === undefined) return;\n  const url = `${baseUrl()}/api/actions/${encodeURIComponent(action.name)}`;\n  await vscode.window.withProgress({ location: vscode.ProgressLocation.Notification, title: `${PRODUCT.name}: ${action.title}` }, async () => {\n    let res;\n    try {\n      res = await fetch(url, { method: \"POST\", headers: { \"content-type\": \"application/json\", accept: \"application/json\" }, body: JSON.stringify(input), redirect: \"error\", signal: AbortSignal.timeout(TIMEOUT_MS) });\n    } catch (err) {\n      out.appendLine(`${action.name}: ${url} couldn't be reached (${err && err.name ? err.name : \"error\"})`);\n      vscode.window.showErrorMessage(`${PRODUCT.name} couldn't be reached. Check your connection, or the address in its settings.`);\n      return;\n    }\n    const text = await res.text();\n    let reply;\n    try {\n      reply = JSON.parse(text);\n    } catch {\n      out.appendLine(`${action.name}: HTTP ${res.status}, not JSON`);\n      vscode.window.showErrorMessage(`${PRODUCT.name} answered with something that isn't JSON (HTTP ${res.status}).`);\n      return;\n    }\n    if (!res.ok) {\n      const said = reply && typeof reply.error === \"string\" ? reply.error.slice(0, 300) : `HTTP ${res.status}`;\n      out.appendLine(`${action.name}: ${said}`);\n      vscode.window.showErrorMessage(`${PRODUCT.name}: ${said}`);\n      return;\n    }\n    const doc = await vscode.workspace.openTextDocument({ language: \"json\", content: `${JSON.stringify(reply, null, 2)}\\n` });\n    await vscode.window.showTextDocument(doc, { preview: true });\n  });\n}\n\nfunction activate(context) {\n  const out = vscode.window.createOutputChannel(PRODUCT.name);\n  context.subscriptions.push(out);\n  for (const action of PRODUCT.actions) {\n    context.subscriptions.push(vscode.commands.registerCommand(action.command, () => run(action, out)));\n  }\n  context.subscriptions.push(vscode.commands.registerCommand(PRODUCT.openCommand, () => vscode.env.openExternal(vscode.Uri.parse(baseUrl()))));\n}\n\nfunction deactivate() {}\n\nmodule.exports = { activate, deactivate, baseUrl, collectInput };\n";

/** The GitHub Action's index.js. It reads the product from product.json beside it. */
export const GITHUB_ACTION_SOURCE: string = "// A GitHub Action for one Muse Muse product, generated from its musemuse.json: it runs one of the product's actions\n// with the JSON input it is given and puts the reply in the step's `result` output and its summary.\n// No dependencies, Node 20 or newer. Built with Muse Muse, a hackathon concept. Not an official Meta product.\n\"use strict\";\n\nconst { appendFileSync } = require(\"node:fs\");\nconst { randomBytes } = require(\"node:crypto\");\nconst PRODUCT = require(\"./product.json\");\n\n/** An input the way the runner passes it: INPUT_ and the name in capitals, spaces as underscores. */\nfunction input(name) {\n  return String(process.env[`INPUT_${name.replace(/ /g, \"_\").toUpperCase()}`] || \"\").trim();\n}\n\n/** A workflow command's message, escaped the way GitHub reads them. */\nfunction escape(text) {\n  return String(text).replace(/%/g, \"%25\").replace(/\\r/g, \"%0D\").replace(/\\n/g, \"%0A\");\n}\n\nfunction fail(message) {\n  process.stdout.write(`::error::${escape(message)}\\n`);\n  process.exitCode = 1;\n}\n\n/** Writes a step output that may span lines, with a delimiter no reply can contain by chance. */\nfunction setOutput(name, value) {\n  const file = process.env.GITHUB_OUTPUT;\n  if (!file) {\n    process.stdout.write(`${name}=${value}\\n`);\n    return;\n  }\n  let delimiter = `MUSEMUSE_${randomBytes(12).toString(\"hex\")}`;\n  while (value.includes(delimiter)) delimiter = `MUSEMUSE_${randomBytes(12).toString(\"hex\")}`;\n  appendFileSync(file, `${name}<<${delimiter}\\n${value}\\n${delimiter}\\n`);\n}\n\nfunction summary(lines) {\n  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${lines.join(\"\\n\")}\\n`);\n}\n\n/** A Markdown code block that the text can't close early. */\nfunction fenced(text, lang) {\n  const longest = Math.max(2, ...[...text.matchAll(/`+/g)].map((m) => m[0].length));\n  const fence = \"`\".repeat(longest + 1);\n  return `${fence}${lang}\\n${text}\\n${fence}`;\n}\n\nasync function main() {\n  const name = input(\"action\") || (PRODUCT.actions[0] && PRODUCT.actions[0].name) || \"\";\n  const action = PRODUCT.actions.find((a) => a.name === name);\n  if (!action) return fail(`${PRODUCT.name} has no action called \"${name.slice(0, 60)}\". It has: ${PRODUCT.actions.map((a) => a.name).join(\", \")}.`);\n  let body;\n  try {\n    body = JSON.parse(input(\"input\") || \"{}\");\n  } catch {\n    return fail(\"The input isn't JSON. Pass the action's input as a JSON object, like '{\\\"text\\\": \\\"...\\\"}'.\");\n  }\n  if (!body || typeof body !== \"object\" || Array.isArray(body)) return fail(\"The input must be a JSON object.\");\n  const base = (input(\"base-url\") || PRODUCT.liveUrl).replace(/\\/+$/, \"\");\n  if (!/^https:\\/\\/[^\\s/]+/.test(base) && !/^http:\\/\\/(localhost|127\\.0\\.0\\.1)(:\\d+)?$/.test(base)) return fail(\"base-url must be an https:// address.\");\n  const seconds = Number(input(\"timeout-seconds\") || 120);\n  const timeoutMs = Number.isFinite(seconds) && seconds > 0 ? Math.min(seconds, 600) * 1000 : 120000;\n  const url = `${base}/api/actions/${encodeURIComponent(action.name)}`;\n  process.stdout.write(`Running ${action.name} on ${base}\\n`);\n  let res;\n  try {\n    res = await fetch(url, { method: \"POST\", headers: { \"content-type\": \"application/json\", accept: \"application/json\" }, body: JSON.stringify(body), redirect: \"error\", signal: AbortSignal.timeout(timeoutMs) });\n  } catch (err) {\n    return fail(`${url} couldn't be reached (${err && err.name === \"TimeoutError\" ? `no answer within ${timeoutMs / 1000} seconds` : \"network error\"}).`);\n  }\n  const text = await res.text();\n  let reply;\n  try {\n    reply = JSON.parse(text);\n  } catch {\n    return fail(`${action.name} answered HTTP ${res.status} with something that isn't JSON.`);\n  }\n  const json = JSON.stringify(reply);\n  setOutput(\"result\", json);\n  setOutput(\"ok\", res.ok ? \"true\" : \"false\");\n  summary([`### ${PRODUCT.name}: ${action.name}`, \"\", fenced(JSON.stringify(reply, null, 2), \"json\")]);\n  if (!res.ok) return fail(`${action.name} failed: ${reply && typeof reply.error === \"string\" ? reply.error.slice(0, 300) : `HTTP ${res.status}`}`);\n  process.stdout.write(`${json.length > 2000 ? `${json.slice(0, 2000)}...` : json}\\n`);\n}\n\nmain().catch((err) => fail(`It stopped: ${err && err.message ? err.message : err}`));\n";

/** The self-host kit's scripts/kit-fetch.mjs, for the public files it leaves out. */
export const KIT_FETCH_SOURCE: string = "// Part of a Muse Muse self-host kit. Downloads the product's larger public files, which the kit leaves out to stay small,\n// from the live product, and checks each one's sha256 against musemuse-kit.json before saving it.\n//   node scripts/kit-fetch.mjs\n// No dependencies, Node 18 or newer. Built with Muse Muse, a hackathon concept. Not an official Meta product.\nimport { createHash } from \"node:crypto\";\nimport { existsSync, mkdirSync, readFileSync, writeFileSync } from \"node:fs\";\nimport path from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), \"..\");\nconst kit = JSON.parse(readFileSync(path.join(ROOT, \"musemuse-kit.json\"), \"utf8\"));\nconst SAFE = /^public\\/[A-Za-z0-9._\\-/ ]+$/;\n\nlet failed = 0;\nfor (const file of kit.fetch ?? []) {\n  const where = path.join(ROOT, file.path);\n  if (!SAFE.test(file.path) || file.path.split(\"/\").some((s) => s === \"..\" || s === \".\")) {\n    console.error(`skipped ${file.path}: not a public file's path`);\n    failed++;\n    continue;\n  }\n  if (existsSync(where) && createHash(\"sha256\").update(readFileSync(where)).digest(\"hex\") === file.sha256) {\n    console.log(`have ${file.path}`);\n    continue;\n  }\n  try {\n    const res = await fetch(file.url, { redirect: \"follow\", signal: AbortSignal.timeout(120_000) });\n    if (!res.ok) throw new Error(`HTTP ${res.status}`);\n    const data = Buffer.from(await res.arrayBuffer());\n    if (createHash(\"sha256\").update(data).digest(\"hex\") !== file.sha256) throw new Error(\"it doesn't match the kit's sha256, so it wasn't saved\");\n    mkdirSync(path.dirname(where), { recursive: true });\n    writeFileSync(where, data);\n    console.log(`got ${file.path}`);\n  } catch (err) {\n    console.error(`couldn't get ${file.path}: ${err.message}`);\n    failed++;\n  }\n}\nprocess.exit(failed ? 1 : 0);\n";
